import{_ as l,o as t,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-121","description":"","frontmatter":{"date":"2021-05-05T22:29:06","title":"写作课作业-121","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/121.md","filePath":"posts/homework/121.md"}'),o={name:"posts/homework/121.md"};function r(p,e,s,n,_,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<blockquote><p>《一年顶十年》之《社群 如何通过社群凝聚更大的力量》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>做社群，好处多多，是非常值得考虑的创业方式。</li><li>钱在哪里，心就在哪里。花钱和不花钱，心态是很不一样的。</li><li>筛选用户——确认意愿，了解用户，减少阻力。</li><li>提高打开完成率——前置筛选，收取押金，充分动员，分级运营，勋章制度。</li><li>活跃社群——收费比较高，用户能量高，分享价值高，连接频率高。</li><li>我们不仅需要好好总结自己社群的文化，还要做好传播工作，这样才能让社群文化发挥出足够的价值，让大家更同频，让社群更有凝聚力。</li><li>采访观是优质社群的标配。</li><li>要想把社群做好，一定要重视线下活动。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>自己没有运营社群，但参与了定投人生课堂，大家是付费进去的，重视程度确实会不一样。</p><p>定投人生课堂在运营是也是采用了小班，采访官，公好，宣传海报，用户故事，线下活动等多种方式来活跃和传播的。</p><p>看了别人参与的线下活动，自己确实也应该多参与。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',14)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
